package com.shopsphere.controller; import com.shopsphere.entity.OrderStatus; import com.shopsphere.service.AdminService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1/admin") @PreAuthorize("hasRole('ADMIN')") public class AdminController {private final AdminService s;public AdminController(AdminService s){this.s=s;} @GetMapping("/dashboard") public Map<String,Object> dashboard(){return s.dashboard();} @PatchMapping("/orders/{id}/status") public void status(@PathVariable UUID id,@RequestParam OrderStatus status){s.updateOrder(id,status);}}